function validate([word, numFriends]) {
  if (word.length < 1 || word.length > 5000) return 'word must have 1 to 5,000 letters.';
  if (!/^[a-z]+$/.test(word)) return 'word may contain only lowercase English letters.';
  if (numFriends < 1 || numFriends > word.length) return 'numFriends is between 1 and the length of word.';
  return null;
}

