function answerString(word, numFriends) {
  if (numFriends === 1) {
    return word;
  }
  const longest = word.length - numFriends + 1;
  let best = '';
  for (let i = 0; i < word.length; i++) {
    const candidate = word.substring(i, i + longest);
    if (candidate > best) {
      best = candidate;
    }
  }
  return best;
}

