function answerString(word, numFriends) {
  // Build every split into numFriends non-empty pieces and look at all of its pieces.
  let best = '';
  const pieces = [];
  const split = (start) => {
    if (pieces.length === numFriends - 1) {
      pieces.push(word.slice(start));
      for (const piece of pieces) if (piece > best) best = piece;
      pieces.pop();
      return;
    }
    for (let end = start + 1; end < word.length; end++) {
      pieces.push(word.slice(start, end));
      split(end);
      pieces.pop();
    }
  };
  split(0);
  return best;
}

