function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 5000 : 1 + Math.floor(rand() * 8);
  // Only a few distinct letters, so ties and shared prefixes are common.
  const letters = 1 + Math.floor(rand() * (large ? 4 : 3));
  const base = 97 + Math.floor(rand() * (27 - letters));
  let word = '';
  for (let k = 0; k < n; k++) word += String.fromCharCode(base + Math.floor(rand() * letters));
  const roll = rand();
  const numFriends = roll < 0.15 ? 1 : roll < 0.3 ? n : 1 + Math.floor(rand() * n);
  return [word, numFriends];
}
